import json
with open('/app/resources/treasury_bulletin_1960_07.json') as f:
    data = json.load(f)

# Let's look for table elements or data around years 1945 and 1950
def find_in_dict(d, target):
    if isinstance(d, dict):
        for k, v in d.items():
            if target in str(k) or target in str(v):
                print(f'Found {target} in key: {k}, value: {str(v)[:200]}')
            find_in_dict(v, target)
    elif isinstance(d, list):
        for item in d:
            find_in_dict(item, target)

find_in_dict(data, '1945')
